        # compute symbol counts among present nodes except this one
        symbol_counts = {}
        for other_id in present:
            if other_id == nid:
                continue
            sym = node_map[other_id]['symbol']
            symbol_counts[sym] = symbol_counts.get(sym, 0) + 1
